using System;namespace SkinFusion {class CloseGameTests {static void Main(){string root=@"D:\Riot Games\League of Legends";if(!GameSession.Matches(root+@"\Game\League of Legends.exe",root))throw new Exception("Game rejected");if(!GameSession.Matches(root.ToLowerInvariant()+@"\game\league of legends.exe",root))throw new Exception("Case mismatch");foreach(string candidate in new[]{root+@"\LeagueClient.exe",root+@"\LeagueClientUx.exe",root+@"\RiotClientServices.exe",root+@"\League of Legends.exe",@"C:\Other\Game\League of Legends.exe"})if(GameSession.Matches(candidate,root))throw new Exception("Unsafe target accepted: "+candidate);if(GameSession.Matches(root+@"\Game\League of Legends.exe",null))throw new Exception("Missing path accepted");dynamic outcome=GameSession.Close(null);if(!outcome.needsPath||outcome.closed!=0)throw new Exception("Missing path should not close processes");var sandbox=System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"test-league");System.IO.Directory.CreateDirectory(System.IO.Path.Combine(sandbox,"Game"));var dummy=System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"DummyGame.exe");var gameFile=System.IO.Path.Combine(sandbox,"Game","League of Legends.exe");var clientFile=System.IO.Path.Combine(sandbox,"LeagueClient.exe");System.IO.File.Copy(dummy,gameFile,true);System.IO.File.Copy(dummy,clientFile,true);using(var game=System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(gameFile){UseShellExecute=false,CreateNoWindow=true}))using(var client=System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(clientFile){UseShellExecute=false,CreateNoWindow=true})){try{dynamic result=GameSession.Close(sandbox);if(result.closed!=1||!game.WaitForExit(3000))throw new Exception("Game was not closed");if(client.HasExited)throw new Exception("Client was closed");}finally{if(!game.HasExited)game.Kill();if(!client.HasExited)client.Kill();}}Console.WriteLine("PASS: real dummy game process closed; dummy League client preserved.");Console.WriteLine("PASS: exact game path accepted, client and unrelated paths excluded; no-path request closes nothing.");}}}